Insert into USERS (ID,DT_INS,CHAT_ID,FIRST_NAME,USERNAME,LAST_NAME,LANGUAGE_CODE,IS_PREMIUM,IS_BOT) values (4043,to_timestamp('14-MAR-23 12.16.26 PM','DD-MON-RR HH.MI.SSXFF AM'),-827356027,'Это группа',null,null,null,null,null);
Insert into COMPLIMENTS (ID,TEXT) values (38,'С тех пор, как ты появилась в моей жизни, мне стало очень трудно замечать кого-то еще. А сейчас, кроме тебя, в моем мире вообще никого не существует.');
Insert into COMPLIMENTS (ID,TEXT) values (39,'Ну вот что ты наделала? Работать не могу, развлекаться не могу, с друзьями тоже сам не свой. Почему? Да потому что только о тебе и думаю.');
Insert into COMPLIMENTS (ID,TEXT) values (40,'Ты такая хрупкая и нежная, что хочется постоянно носить на руках и оберегать от всего плохого.');
Insert into COMPLIMENTS (ID,TEXT) values (41,'Не хочу отпускать тебя туда одну, вдруг кто-то украдет такое сокровище!');
Insert into COMPLIMENTS (ID,TEXT) values (42,'Я хочу засыпать и просыпаться с тобой, видеть твою сонную мордашку каждое утро и будить тебя поцелуями.');
Insert into COMPLIMENTS (ID,TEXT) values (43,'Я знаю, что ты самостоятельная взрослая девушка, но ничего не могу с собой поделать. Хочу заботиться о тебе все время.');
Insert into COMPLIMENTS (ID,TEXT) values (44,'Милая, родная, самая лучшая, ты — моя радость и вдохновение.');
Insert into COMPLIMENTS (ID,TEXT) values (45,'Можно я тебя обниму и больше не буду отпускать? Серьезно, отпускать тебя из объятий с каждым разом становится все сложнее.');
Insert into COMPLIMENTS (ID,TEXT) values (46,'Давай я заправлю этот непослушный локон за ушко. Нет-нет, он тебе очень идет и выглядит мило. Мне просто хотелось тебя коснуться.');
Insert into COMPLIMENTS (ID,TEXT) values (47,'Я боюсь сделать что-то не так. Твои ранимость и чувственность делают тебя такой хрупкой, но такой нежной, женственной и прекрасной.');
Insert into COMPLIMENTS (ID,TEXT) values (48,'Я не хочу казаться навязчивым, но у тебя настолько сладкие пальчики и сахарные губки, что мне все время хочется целовать их.');
Insert into COMPLIMENTS (ID,TEXT) values (49,'Каждый раз, когда ты рядом, у меня ощущение, что весь мир становится более красочным и удивительным.');
Insert into COMPLIMENTS (ID,TEXT) values (50,'Смотрю на тебя — и хочется сажать лесополосы, строить жилые комплексы и воспитывать целое поколение.');
Insert into COMPLIMENTS (ID,TEXT) values (51,'У тебя точно жар, температура градусов так под 40. Нет? А как же ты опьяняешь меня тогда?');
Insert into COMPLIMENTS (ID,TEXT) values (52,'Я не умею делать сальто, а вот мое сердце научилось, когда увидело тебя.');
Insert into COMPLIMENTS (ID,TEXT) values (53,'Ну ты хотя бы огнетушитель с собой носила, раз так выглядишь.');
Insert into COMPLIMENTS (ID,TEXT) values (54,'Нарушаем, девушка? Где предупредительная табличка “Осторожно! Вызывает бессонницу, рассеянность и влюбленность”?');
Insert into COMPLIMENTS (ID,TEXT) values (55,'В детстве мечтал стать пиратом. Похоже, стал. Ром пил, бороду отпускал, на корабле плавал, теперь вот клад нашел.');
Insert into COMPLIMENTS (ID,TEXT) values (56,'Говорят, нужно брать от жизни только самое лучшее. Так что я тебя забираю.');
Insert into COMPLIMENTS (ID,TEXT) values (57,'Мне не нужно было спрашивать, где ты. А и так понял, что ты где-то рядом, когда увидел кучу мужчин со светящимися глазами.');
Insert into COMPLIMENTS (ID,TEXT) values (58,'Ты вот просто улыбнулась, а у меня капитуляция мозга произошла.');
Insert into COMPLIMENTS (ID,TEXT) values (59,'Мне друг сказал, что его девушка самая лучшая во всем мире. Смотрю на тебя и думаю — вре-е-е-е-ет он, зараза.');
Insert into COMPLIMENTS (ID,TEXT) values (60,'Ты так мило морщишь носик, когда смеешься (нервничаешь, смущаешься, чихаешь).');
Insert into COMPLIMENTS (ID,TEXT) values (61,'Мне нравится, когда ты накручиваешь локон на палец. Выглядишь такой озорной и обаятельной.');
Insert into COMPLIMENTS (ID,TEXT) values (62,'Обожаю, когда ты начинаешь неосознанно покусывать (облизывать) губы. Это так сексуально.');
Insert into COMPLIMENTS (ID,TEXT) values (63,'Потягиваешься, как кошечка. Так и хочется погладить.');
Insert into COMPLIMENTS (ID,TEXT) values (64,'Ты всегда так приятно мурлыкаешь, когда пробуешь это блюдо. Официант, принесите еще три такие порции, пожалуйста.');
Insert into COMPLIMENTS (ID,TEXT) values (65,'Категорически не могу ссориться с тобой. Ты, когда злишься, так сопеть умилительно начинаешь. Невозможно обижаться.');
Insert into COMPLIMENTS (ID,TEXT) values (66,'Когда ты чем-то сильно увлечена, то склоняешь голову набок (показываешь язычок, забавно хмуришься, перебираешь волосы). На тебя всегда приятно и интересно смотреть.');
Insert into COMPLIMENTS (ID,TEXT) values (67,'Я так люблю, когда ты кладешь голову мне на плечо. Ты в эти моменты кажешься такой маленькой и беззащитной.');
Insert into COMPLIMENTS (ID,TEXT) values (68,'Меня успокаивает то, как ты гладишь меня по голове (смотришь на меня, обнимаешь, целуешь), когда я расстроен. Спасибо.');
Insert into COMPLIMENTS (ID,TEXT) values (69,'Ты видела свое выражение лица, когда ты счастлива (взволнована, серьезна, растеряна)? Как тут не влюбиться?');
Insert into COMPLIMENTS (ID,TEXT) values (70,'Благодаря тебе мне хочется быть лучше, сильнее, успешнее.');
Insert into COMPLIMENTS (ID,TEXT) values (71,'Твоя поддержка заставляет меня чувствовать, будто я горы свернуть могу.');
Insert into COMPLIMENTS (ID,TEXT) values (72,'Я действительно счастлив с тобой. И это полностью твоя заслуга.');
Insert into COMPLIMENTS (ID,TEXT) values (73,'Твои слова всегда вдохновляют меня и усиливают уверенность в собственных силах.');
Insert into COMPLIMENTS (ID,TEXT) values (74,'Моя жизнь действительно стала намного лучше после того, как я познакомился с тобой.');
Insert into COMPLIMENTS (ID,TEXT) values (75,'Я не самый сдержанный (открытый, решительный, аккуратный) человек. Но твое присутствие заставляет меня меняться в лучшую сторону.');
Insert into COMPLIMENTS (ID,TEXT) values (76,'Чтобы я делал без твоих советов (золотых рук, помощи, борщей)?');
Insert into COMPLIMENTS (ID,TEXT) values (77,'Когда мне бывает сложно, я вспоминаю, что ты всегда рядом и любишь меня, и мне становится намного легче.');
Insert into COMPLIMENTS (ID,TEXT) values (78,'Спасибо за то, что заботишься обо мне. Это приятно и очень важно для меня.');
Insert into COMPLIMENTS (ID,TEXT) values (79,'Ты одна знаешь, как заставить меня смеяться (переосмыслить что-то, увидеть положительное, продолжать бороться).');
Insert into COMPLIMENTS (ID,TEXT) values (80,'Ты рисуешь (шьешь одежду, занимаешься хенд-мейдом)? Должно быть, у тебя потрясающий вкус и чувство стиля.');
Insert into COMPLIMENTS (ID,TEXT) values (81,'Танцуешь? Надеюсь, ты когда-нибудь покажешь мне. Уверен, ты очень красиво двигаешься.');
Insert into COMPLIMENTS (ID,TEXT) values (82,'Поешь? А я как раз подумал, какой у тебя красивый и мелодичный голос.');
Insert into COMPLIMENTS (ID,TEXT) values (83,'Любишь помогать людям? Очень приятно осознавать, что я встретил такую добрую и отзывчивую девушку.');
Insert into COMPLIMENTS (ID,TEXT) values (84,'Нравится проводить время с друзьями? Наверное, ты душа компании. С тобой действительно очень интересно общаться.');
Insert into COMPLIMENTS (ID,TEXT) values (85,'Играешь на музыкальном инструменте? Уверен, у тебя безупречный слух. Да и такие пальчики могут создавать только самые красивые звуки — 100%. Сыграешь как-нибудь?');
Insert into COMPLIMENTS (ID,TEXT) values (86,'Занимаешься спортом? Тебе даже не нужно было об этом говорить, твоя фигура все сказала за тебя.');
Insert into COMPLIMENTS (ID,TEXT) values (87,'Пишешь стихи (прозу, пьесы)? Тогда у тебя точно очень хорошее воображение. Не представляю, как можно сочинять. Ты удивительная девушка.');
Insert into COMPLIMENTS (ID,TEXT) values (88,'Много читаешь? Порекомендуешь что-нибудь? Мне почему-то кажется, что ты сразу же угадаешь книгу, которая мне понравится.');
Insert into COMPLIMENTS (ID,TEXT) values (89,'Увлекаешься кулинарией? Так, все, переезжай ко мне. Серьезно, такой интерес очень радует. Ты же просто находка.');
Insert into COMPLIMENTS (ID,TEXT) values (90,'Это не ты играла главную роль в «Чудо-женщине»? Странно, а фильм явно о тебе.');
Insert into COMPLIMENTS (ID,TEXT) values (91,'Я когда тебя вижу, то все мои 50 оттенков серого окрашиваются в ярко-красный.');
Insert into COMPLIMENTS (ID,TEXT) values (92,'Я, конечно, не Ричард Гир, но ты та еще красотка.');
Insert into COMPLIMENTS (ID,TEXT) values (93,'Рядом с тобой я Брюс Всемогущий.');
Insert into COMPLIMENTS (ID,TEXT) values (94,'Хочется оберегать тебя, как Маленький принц свою Розу.');
Insert into COMPLIMENTS (ID,TEXT) values (95,'Моя жизнь превратилась в Страну Чудес, когда ты появилась в ней.');
Insert into COMPLIMENTS (ID,TEXT) values (96,'Шрама на лбу у меня нет, очков не ношу. Как же я сумел наколдовать себе такую прелесть?');
Insert into COMPLIMENTS (ID,TEXT) values (97,'Ты моя Маргарита, ради которой я готов стать Мастером на все руки.');
Insert into COMPLIMENTS (ID,TEXT) values (98,'Ты мой самый-самый редкий и красивый Аленький цветочек.');
Insert into COMPLIMENTS (ID,TEXT) values (99,'Ты моя Маркиза ангелов — нежная, соблазнительная, чувственная.');
Insert into COMPLIMENTS (ID,TEXT) values (100,'Ты – самое ценное в моей жизни, ты – настоящее сокровище, что делает меня самым богатым человеком в мире.');
Insert into COMPLIMENTS (ID,TEXT) values (101,'На планете есть семь чудес света, но есть еще одно, самое очаровательное и красивое - это ты!');
Insert into COMPLIMENTS (ID,TEXT) values (102,'Наверняка ты знаешь какой-то секрет красоты, иначе как объяснить твою сногсшибательность?');
Insert into COMPLIMENTS (ID,TEXT) values (103,'Бог наделяет каждого уникальными качествами. Кто-то красив, кто-то умён, таланты одних видны всем, а таланты других надо разглядеть. Но при создании тебя у Бога было особое вдохновение!');
Insert into COMPLIMENTS (ID,TEXT) values (104,'Ты - та, о ком я думаю каждую секунду, минуту, час, сутки!');
Insert into COMPLIMENTS (ID,TEXT) values (105,'Нет на Земле девушки прекраснее, чем ты, и нет мужчины счастливее, чем я, потому что возможность обнимать тебя – это и есть высшее счастье!');
Insert into COMPLIMENTS (ID,TEXT) values (106,'Ты мой ясный лучик, благодаря тебе я ежедневно просыпаюсь с улыбкой, ведь ты первое, о чем я думаю после пробуждения! Весь мир прекрасен, полон ярких красок и света, если ты рядом, мое солнце!');
Insert into COMPLIMENTS (ID,TEXT) values (107,'На первый взгляд ты кажешься такой хрупкой, но своим взглядом хоть кого отправишь в нокаут!');
Insert into COMPLIMENTS (ID,TEXT) values (108,'Дорогая, ты мое личное солнце, которое освещает дорогу моей жизни и делает ее прекраснее! Твоя яркая, лучезарная улыбка сводит меня с ума, а в твоих ясных глазах я тону, словно в безграничном океане!');
Insert into COMPLIMENTS (ID,TEXT) values (109,'Страсть и нежность, тонкий ум и феноменальная красота, стойкость духа и трогательная беззащитность – всё это сочетается в тебе, любимая! Таких, как ты, больше нет!');
Insert into COMPLIMENTS (ID,TEXT) values (110,'Когда ты рядом я становлюсь счастливее и сильнее. Ведь ты само совершенство, эталон красоты, ума и женственности.');
Insert into COMPLIMENTS (ID,TEXT) values (111,'Ты не просто прекрасна, ты восхитительна! И любое сравнение – с ясным солнышком, сверкающей звездой, изысканным цветком – будет в твою пользу!');
Insert into COMPLIMENTS (ID,TEXT) values (112,'Сладкая моя девочка, ты – прекраснее всех в этом мире! Я счастлив, что могу вдыхать запах твоих волос, целовать твои губы и просто видеть, как ты улыбаешься!');
Insert into COMPLIMENTS (ID,TEXT) values (113,'Во Вселенной много прекрасных и ярких звезд, но моя путеводная – это ты. Твой свет завораживает и ведет к счастью.');
Insert into COMPLIMENTS (ID,TEXT) values (114,'Дорогая, красота твоих сияющих глаз несоизмерима даже с яркими звездами, роскошь длинных волос - ни с одним водопадом, а бархатная, нежная кожа не сравнится даже с лепестками самой прекрасной розы!');
Insert into COMPLIMENTS (ID,TEXT) values (115,'Это огромное счастье находится рядом с эталоном шарма, красоты и женственности. Рядом с тобой, моя любимая.');
Insert into COMPLIMENTS (ID,TEXT) values (116,'Ты – совершенна! Я могу бесконечно любоваться утончёнными чертами твоего лица! Твой нежный голос ласкает слух, а твои объятия – дарят райское наслаждение!');
Insert into COMPLIMENTS (ID,TEXT) values (117,'Я не могу поверить в то, что я встретил такую очаровательную девушку как ты!');
Insert into COMPLIMENTS (ID,TEXT) values (118,'Каждое мгновение, когда ты рядом, для меня счастье. Моя душа поет в такие минуты, а сердце учащенно бьется.');
Insert into COMPLIMENTS (ID,TEXT) values (119,'При одной мысли о тебе мое сердцебиение учащается, ведь такой прекрасной, очаровательной девушки больше нет на всей планете!');
Insert into COMPLIMENTS (ID,TEXT) values (120,'Ты безумно красивая, твои глаза, словно две яркие звездочки, щечки, как румяные яблочки, а губы, будто только что распустившийся бутон розы!');
Insert into COMPLIMENTS (ID,TEXT) values (121,'Ты - самое лучшее, что со мной приключилось в жизни!');
Insert into COMPLIMENTS (ID,TEXT) values (122,'Ты зажгла в моей душе пламя любви и страсти. И для этого тебе было достаточно всего лишь улыбнуться.');
Insert into COMPLIMENTS (ID,TEXT) values (123,'Любимая, ты наполняешь мою жизнь радостью, счастьем и уютом. Только рядом с тобой я дышу полной грудью.');
Insert into COMPLIMENTS (ID,TEXT) values (124,'Я хочу подарить тебе весь мир вокруг! Просто потому, что не могу жить без тебя!');
Insert into COMPLIMENTS (ID,TEXT) values (125,'Любимая, ты – мой воздух, кристально чистый и свежий, и я не могу тобой надышаться! Я бесконечно благодарен тебе за твою доброту, чуткость, искренность, а небесам – за нашу встречу!');
Insert into COMPLIMENTS (ID,TEXT) values (126,'Все считают, что солнце находится на небе, но я-то знаю, что солнце всегда со мной, освещает мою жизнь и согревает своим теплом!');
Insert into COMPLIMENTS (ID,TEXT) values (127,'Я ослеплен твоей прелестной красотой, ведь ты похожа на ангела, который спустился с небес! Ты шикарна от кончиков ресниц до кончиков пальцев! Любуюсь и восхищаюсь тобой, ты само совершенство!');
Insert into COMPLIMENTS (ID,TEXT) values (128,'Когда я смотрю в твои очаровательные глаза, я вижу взгляд ангела!');
Insert into COMPLIMENTS (ID,TEXT) values (129,'Дорогая, ты – прекрасная причина, чтобы любить жизнь и наслаждаться каждым ее мгновением.');
Insert into COMPLIMENTS (ID,TEXT) values (130,'Для меня нет в жизни больше цели, кроме как сделать тебя счастливой!');
Insert into COMPLIMENTS (ID,TEXT) values (131,'С каждой нашей встречей ты все больше и больше меня приятно удивляешь! Я узнаю тебя с новых сторон, и твоя многогранность меня приводит в восторг! Ты шикарная девушка во всех смыслах этого слова и я очаровываюсь тобой снова и снова!');
Insert into COMPLIMENTS (ID,TEXT) values (132,'Солнышко, ты такая удивительно прекрасная девушка, ты мой бриллиант, который с каждым днем открывает для меня все новые и новые грани! Сияй, дорогая, и просто будь собой, ведь я ценю твою естественность и искренность!');
Insert into COMPLIMENTS (ID,TEXT) values (133,'Ты такая великолепная, что я просто не могу оторвать от тебя взгляда, для меня нет большего счастья, чем быть рядом с тобой');
Insert into COMPLIMENTS (ID,TEXT) values (134,'Твое обаяние обезоруживает, красота чарует, шарм заставляет терять голову, а мудрость и доброта восхищают.');
Insert into COMPLIMENTS (ID,TEXT) values (135,'Ты изменила мою жизнь и меня самого. Ты наполнила особым, прекрасным смыслом каждое мгновение.');
Insert into COMPLIMENTS (ID,TEXT) values (136,'Знаешь, я так счастлив, что мне досталась самая красивая, умная, заботливая и добрая девушка на свете! Ты лучшее, что случалось со мной в этой жизни и я всегда буду беречь тебя, словно бесценное сокровище!');
Insert into COMPLIMENTS (ID,TEXT) values (137,'Душевное тепло твоих чар помогло растопить лёд в моём сердце');
Insert into COMPLIMENTS (ID,TEXT) values (138,'Любимая, твоя красота - это настоящее произведение искусства, голос - музыка для моей души, а прикосновения - это касания нежного шелка! С каждым днем я влюбляюсь в тебя все сильнее, моя принцесса!');
Insert into COMPLIMENTS (ID,TEXT) values (139,'Я обожаю твою солнечную улыбку, твой ласковый голос, и я готов на всё, чтобы видеть в твоих глазах счастливый блеск! Ты божественно прекрасна, моя любимая!');
Insert into COMPLIMENTS (ID,TEXT) values (140,'Ты – мой идеал, а наша любовь – награда судьбы. Она дарит мне крылья за спиной, и я готов взлететь к небесам, чтобы достать для тебя самую яркую звезду!');
Insert into COMPLIMENTS (ID,TEXT) values (141,'В тебе есть шарм и благородство, красота и обаяние, мудрость и непредсказуемость. Ты просто идеальная женщина.');
Insert into COMPLIMENTS (ID,TEXT) values (142,'Моя душа утопает в твоих глубоких, очаровательных глазах!');
Insert into COMPLIMENTS (ID,TEXT) values (143,'Ты таинственна и бесподобна, неповторима и как всегда очаровательна. Быть с тобой одно удовольствие!');
Insert into COMPLIMENTS (ID,TEXT) values (144,'Моя дорогая, несравненная богиня красоты, я никогда не встречал таких очаровательных девушек, как ты! Я обожаю твой взгляд, твои сладкие поцелуи, твою лучезарную улыбку и звонкий смех! Ты единственная и неповторимая!');
Insert into COMPLIMENTS (ID,TEXT) values (145,'Твоя красота и жизненная сила манят и завораживают, вдохновляют и толкают на большие свершения.');
Insert into COMPLIMENTS (ID,TEXT) values (146,'Мне жаль, что ты встретилась мне только сейчас. Я был бы в миллион раз счастливее, если бы это произошло раньше!');
Insert into COMPLIMENTS (ID,TEXT) values (147,'Прекраснее тебя может быть только твоя дочь!');
Insert into COMPLIMENTS (ID,TEXT) values (148,'Нет прекраснее мгновений, чем минуты, проведенные с тобою!');
Insert into COMPLIMENTS (ID,TEXT) values (149,'Как замечательно, когда внешняя красота дополняется прекрасными душевными качествами! Я нашел в тебе все, что искал! Спасибо тебе, солнышко, за то, что ты такая!');
Insert into COMPLIMENTS (ID,TEXT) values (150,'Ты хозяйка моего сердца, повелительница души и всей жизни. И это счастье быть во власти такой восхитительной женщины как ты.');
Insert into COMPLIMENTS (ID,TEXT) values (151,'Мне досталась самая великолепная девушка на Земле! Я люблю тебя, дорогая!');
Insert into COMPLIMENTS (ID,TEXT) values (152,'Моя королева, никто и ничто не сможет сравниться с твоей неописуемой красотой! Я люблю тебя от кончиков пальчиков до кончиков ресниц! Ты шикарна, помни это!');
Insert into COMPLIMENTS (ID,TEXT) values (153,'Солнышко, ты такая удивительно прекрасная девушка, ты мой бриллиант, который с каждым днем открывает для меня все новые и новые грани! Сияй, дорогая, и просто будь собой, ведь я ценю твою естественность и искренность!');
Insert into COMPLIMENTS (ID,TEXT) values (154,'Такую девушку я не встречал - красивую, нежную, добрую, милую, одним словом - неповторимую!');
Insert into COMPLIMENTS (ID,TEXT) values (155,'Дорогая, у меня нет слов, чтобы описать, насколько ты прекрасный, светлый человечек! Знай, что у тебя бесконечное множество достоинств, а даже то, что ты считаешь своими недостатками, на самом деле твои изюминки, которые я люблю и принимаю!');
Insert into COMPLIMENTS (ID,TEXT) values (156,'Любимая, ты подобна яркому цветку, который с каждым днем становится все ярче, красивее и раскрывается с новых удивительно прекрасных сторон! Ты невероятная девушка, в которой сочетаются и внешняя красота, и духовная, что встречается так редко!');
Insert into COMPLIMENTS (ID,TEXT) values (157,'Дорогая, рядом с тобой я чувствую себя настоящим мужчиной, ведь ты такая нежная, хрупкая и женственная, и вызываешь желание постоянно любить, ценить и оберегать тебя!');
Insert into COMPLIMENTS (ID,TEXT) values (158,'Милая, ты прекрасней летних рассветов и закатов, красивее всех цветов и ярче всех звезд во вселенной!');
Insert into COMPLIMENTS (ID,TEXT) values (159,'Я схожу с ума от твоих поцелуев и прикосновений, от твоей бархатной кожи и точеной фигурки! Ты настоящая богиня красоты и обольщения, которую мне посчастливилось встретить в реальной жизни!');
Insert into COMPLIMENTS (ID,TEXT) values (160,'Я восхищаюсь тобой снова и снова! Как приятно осознавать, что мне досталась лучшая девушка во вселенной!');
Insert into COMPLIMENTS (ID,TEXT) values (161,'Ты мое вдохновение, ради тебя я готов становиться лучше, ведь всю свою жизнь я хочу делать тебя счастливой, моя королева!');
Insert into COMPLIMENTS (ID,TEXT) values (162,'Наверное, я попал в сказку, ведь такие очаровательные принцессы живут только там! Я очарован твоей неописуемой красотой, твоим добрым сердцем и твоими прекрасными манерами! Ты настоящая прелестная леди, и меня тянет к тебе, словно магнитом!');
Insert into COMPLIMENTS (ID,TEXT) values (163,'Сияние твоей улыбки, дорогая, меня ослепляет, блеск твоих глаз сводит с ума, а красота тела заставляет биться сердце быстрее! До чего же ты обворожительна, моя богиня, невозможно описать словами!');
Insert into COMPLIMENTS (ID,TEXT) values (164,'Я уверен, ни одна Мисс мира не сравнится с тобой, моя дорогая, ведь такого сочетания красоты, ума, мудрости, обаяния и множества талантов я не встречал никогда! Ты совершенна, идеальна и неповторима, моя любимая!');
Insert into COMPLIMENTS (ID,TEXT) values (165,'Ты прекрасна, словно невиданной красоты цветок! Ты невероятно милая, добрая и мудрая девушка! Быть рядом с тобой - для меня наивысшая награда!');
Insert into COMPLIMENTS (ID,TEXT) values (166,'Говорят, что идеальных людей не существует, но при взгляде на тебя я понимаю, что эти слова ошибочны. Ты – само совершенство!');
Insert into COMPLIMENTS (ID,TEXT) values (167,'С той минуты, как я понял, что люблю тебя, мне больше не к чему стремиться в жизни!');
Insert into COMPLIMENTS (ID,TEXT) values (168,'Спасибо твоим родителям за то, что создали такое чудо (в самом хорошем смысле этого слова), как ты! Прекрасные черты лица, точеная фигура, доброе сердце и хорошие манеры - это все о тебе! Ты прелестна, помни об этом!');
Insert into COMPLIMENTS (ID,TEXT) values (1,'Ты знала, что, когда улыбаешься, то у тебя на щеках появляются ямочки? Они такие милые.');
Insert into COMPLIMENTS (ID,TEXT) values (2,'У тебя шикарный цвет глаз, такой насыщенный (глубокий, яркий, редкий, мягкий). Кстати, это мой любимый оттенок.');
Insert into COMPLIMENTS (ID,TEXT) values (3,'Улыбайся, пожалуйста, почаще. У тебя сразу начинают глаза блестеть, и ты выглядишь потрясающе.');
Insert into COMPLIMENTS (ID,TEXT) values (4,'У тебя такая тонкая талия (изящные кисти, плавная линия плеч). Мне очень нравится твоя женственность.');
Insert into COMPLIMENTS (ID,TEXT) values (5,'Потрясающая фигура! Тебя легко принять за фитнес-тренера или спортсменку.');
Insert into COMPLIMENTS (ID,TEXT) values (6,'Ммм, такая нежная (бархатистая, гладенькая, мягкая) кожа. Ты, наверное, очень тщательно ухаживаешь за ней.');
Insert into COMPLIMENTS (ID,TEXT) values (7,'Ты настолько изумительна, что мне хочется стать художником и запечатлеть все твои линии, ямочки, тени на холсте.');
Insert into COMPLIMENTS (ID,TEXT) values (8,'Ты очень красива без макияжа, а твоя естественная красота видна сразу. Это большая редкость.');
Insert into COMPLIMENTS (ID,TEXT) values (9,'Прости, засмотрелся на тебя и потерял мысль. Ты не могла бы повторить все еще раз?');
Insert into COMPLIMENTS (ID,TEXT) values (10,'Всегда мечтал о такой доброй (ласковой, нежной, заботливой, чуткой) женщине. Я счастлив, что встретил тебя.');
Insert into COMPLIMENTS (ID,TEXT) values (11,'Твоя целеустремленность (сила воли, уверенность, настойчивость, любые сильные качества) заслуживает похвал. Я искренне горжусь тобой.');
Insert into COMPLIMENTS (ID,TEXT) values (12,'Спасибо за то, что всегда стараешься меня понять. Для меня очень ценны твои миролюбие, неконфликтность и умение идти на компромисс.');
Insert into COMPLIMENTS (ID,TEXT) values (13,'Спасибо за твою искренность и открытость. Ты не представляешь, насколько они для меня важны.');
Insert into COMPLIMENTS (ID,TEXT) values (14,'Порой ты тихая и немного замкнутая, но это делает тебя такой таинственной. Мне нравится твоя загадочность и скромность.');
Insert into COMPLIMENTS (ID,TEXT) values (15,'С тобой никогда не заскучаешь. Ты веселая, активная и жизнерадостная. Ты же всегда будешь такой, правда-правда?');
Insert into COMPLIMENTS (ID,TEXT) values (16,'Ты сама это придумала (сделала)? Какая ты молодец! Очень красиво (креативно, необычно, находчиво).');
Insert into COMPLIMENTS (ID,TEXT) values (17,'Я уважаю твое стремление совершенствоваться и становиться еще лучше. Хотя мне каждый раз кажется, что лучше уже некуда. Но ты всегда приятно меня удивляешь.');
Insert into COMPLIMENTS (ID,TEXT) values (18,'Родная, спасибо за верность и преданность. Я рад, что могу быть спокоен и доверять тебе на все 100%.');
Insert into COMPLIMENTS (ID,TEXT) values (19,'У тебя потрясающий вкус. Я не знаю, чтобы я делал без твоей бережливости, аккуратности и хозяйственности.');
Insert into COMPLIMENTS (ID,TEXT) values (20,'Обожаю твои изящные изгибы форм. Они будоражат мою кровь.');
Insert into COMPLIMENTS (ID,TEXT) values (21,'Хочется целовать каждый сантиметр твоего тела и все время наслаждаться тобой.');
Insert into COMPLIMENTS (ID,TEXT) values (22,'Без ума от твоей походки. Каждый шаг, каждое движение бедрами дразнит, манит и чертовски заводит.');
Insert into COMPLIMENTS (ID,TEXT) values (23,'Как, по-твоему, я должен держать себя в руках, если ты так сногсшибательно выглядишь?');
Insert into COMPLIMENTS (ID,TEXT) values (24,'Рядом с тобой мне постоянно приходится контролировать себя. Если бы не все эти люди вокруг…');
Insert into COMPLIMENTS (ID,TEXT) values (25,'Мне безумно хочется тебя обнять прямо сейчас, но я боюсь, что, сделав это, уже не смогу удержаться от продолжения.');
Insert into COMPLIMENTS (ID,TEXT) values (26,'Можешь сказать это еще раз? У тебя такой сексуальный тембр голоса.');
Insert into COMPLIMENTS (ID,TEXT) values (27,'Прекрати так улыбаться (смотреть, делать, говорить), иначе я сейчас прямо здесь тебя раздену и наброшусь.');
Insert into COMPLIMENTS (ID,TEXT) values (28,'Что я думаю о твоем внешнем виде? Скажем так, если бы существовал измеритель сексуальности, то рядом с тобой он бы уже давно взорвался от перегрузки.');
Insert into COMPLIMENTS (ID,TEXT) values (29,'Ты — мой личный афродизиак. Волнуешь, возбуждаешь, отключаешь голову, играешь со мной.');
Insert into COMPLIMENTS (ID,TEXT) values (30,'Я не хочу видеть рядом кого-либо, кроме тебя. Ты — моя единственная, и я твердо в этом уверен.');
Insert into COMPLIMENTS (ID,TEXT) values (31,'Ты — это самый лучший выбор, который я сделал за свою жизнь. Я рад, что судьба свела нас вместе.');
Insert into COMPLIMENTS (ID,TEXT) values (32,'Спасибо за то, что делаешь меня счастливым, я еще никогда не испытывал такой радости и блаженства.');
Insert into COMPLIMENTS (ID,TEXT) values (33,'Я понятия не имею, есть ли там наверху кто-то, кто предназначает людей друг для друга. Но если предположить, что это так, то ты точно моя половина.');
Insert into COMPLIMENTS (ID,TEXT) values (34,'Я не встречал таких, как ты. Ты действительно особенная и неповторимая.');
Insert into COMPLIMENTS (ID,TEXT) values (35,'Зачем мне думать или мечтать о первых красавица мира, если у меня есть ты?');
Insert into COMPLIMENTS (ID,TEXT) values (36,'Я хочу, чтобы то, что есть между нами, длилось очень и очень долго. Нет, не так. Хочу, чтобы это было навсегда и именно с тобой.');
Insert into COMPLIMENTS (ID,TEXT) values (37,'Мне трудно выразить свои чувства к тебе, потому что таких сильных эмоций я никогда не испытывал.');
Insert into COMPLIMENTS (ID,TEXT) values (169,'Моя любимая, даже всемирно известные эталоны красоты не могут сравниться с тобой: каждая черта твоего лица прекрасна, фигура изящна, а ум, мудрость, грация и элегантность - твои главные козыри!');
Insert into COMPLIMENTS (ID,TEXT) values (170,'Сказать, что твоя красота покорила меня - это ничего не сказать! Твое внешнее очарование так гармонирует с внутренним богатым миром, что я до сих пор пребываю в восхищении! Ты мой реальный идеал, который я и не надеялся встретить в этой жизни!');
Insert into COMPLIMENTS (ID,TEXT) values (171,'Любимая, та настоящая принцесса из сказки: красивая, умная, талантливая. В твою честь хочется покорять вершины и совершать подвиги.');
Insert into COMPLIMENTS (ID,TEXT) values (172,'Ты – сверкающий бриллиант, ценность которого невозможно измерить!');
Insert into COMPLIMENTS (ID,TEXT) values (173,'Ты насколько потрясающая девушка, что, когда ты рядом, я завидую самому себе!');
Insert into COMPLIMENTS (ID,TEXT) values (174,'У тебя глаза, как два драгоценных камня - яркие, мерцают ослепительным блеском!');
Insert into COMPLIMENTS (ID,TEXT) values (175,'Моя главная цель в жизни - это любить тебя всегда!');
Insert into COMPLIMENTS (ID,TEXT) values (176,'В тебе идеально сочетаются ум, красота, женское обаяние и лучшие человеческие качества!');
Insert into COMPLIMENTS (ID,TEXT) values (177,'Ты для меня словно луч солнца в дождливый день. Ты озаряешь мою жизнь светом красоты и согреваешь своим очарованием.');
Insert into COMPLIMENTS (ID,TEXT) values (178,'Ты не просто девушка, ты – богиня! Ты знаешь, как очаровать любого, а я знаю, что буду любить тебя вечно!');
Insert into COMPLIMENTS (ID,TEXT) values (179,'Как прекрасно, что я встретил тебя, моя дорогая, ведь ты самая красивая, обворожительная, шикарная и просто неповторимая девушка! Ты очаровываешь меня с каждым днем все сильнее, и я влюбляюсь в тебя снова и снова!');
Insert into COMPLIMENTS (ID,TEXT) values (180,'Дорогая, я гляжу на тебя и восхищаюсь твоими прелестными чертами лица, жестами и манерами, твоей фигурой, твоим нежным голосом и красивой речью, и задаюсь вопросом: неужели я смог отыскать среди обычных женщин эту прекрасную богиню?!');
Insert into COMPLIMENTS (ID,TEXT) values (181,'Приятно находиться рядом с воплощением красоты, с тобой, любимая!');
Insert into COMPLIMENTS (ID,TEXT) values (182,'Ты не выходишь из моих мыслей даже на минуту. Ведь невозможно не думать о такой прекрасной и обаятельной девушке.');
Insert into COMPLIMENTS (ID,TEXT) values (183,'Моя богиня красоты и очарования, ты та, с кем я чувствую себя самым счастливым мужчиной! Ты прекрасна и внешне, и душой! Ты такая жизнерадостная, добрая, нежная и женственная! Я очень рад, что однажды судьба свела меня с такой чудесной девушкой!');
Insert into COMPLIMENTS (ID,TEXT) values (184,'Ты – моё солнышко. Ведь свет твоей любви – единственный источник моего вдохновения!');
Insert into COMPLIMENTS (ID,TEXT) values (185,'Дорогая, ты настолько прекрасна, что это невозможно выразить словами! Я так люблю твою улыбку, твой чарующий взгляд, грациозную походку, твой нежный голос...');
Insert into COMPLIMENTS (ID,TEXT) values (186,'Милая, ты совершенна! В тебе чудесным образом сочетаются прекрасный характер, жизненная мудрость и ослепительная красота.');
Insert into COMPLIMENTS (ID,TEXT) values (187,'Я тону в твоих глазах и теряю голову от одной твоей улыбки, а твои объятия – это плен в который я сдаюсь без боя.');
Insert into COMPLIMENTS (ID,TEXT) values (188,'Ты – самая восхитительная, очаровательная, нежная, добрая, милая. Не хватит и жизни, чтобы перечислить все твои прекрасные черты!');
Insert into COMPLIMENTS (ID,TEXT) values (189,'Ты – просто волшебница, очаровавшая меня с первого взгляда и превратившая мою жизнь в сказку!');
Insert into COMPLIMENTS (ID,TEXT) values (190,'Ты, словно принцесса из сказки: красива, умна и добра! Ты очаровываешь каждого, кого встречаешь на своем пути, неповторимой красотой, неотразимым обаянием и светлой душой! Ты излучаешь только позитив, и это прекрасно! Оставайся такой всегда!');
Insert into COMPLIMENTS (ID,TEXT) values (191,'Ангелы живут не только в небесах. По крайней мере, один, самый прекрасный, - уж точно. Я говорю о тебе, любимая. Ты – мой ангел-хранитель! Ты – воплощение нежности, добра и красоты!');
Insert into COMPLIMENTS (ID,TEXT) values (192,'Я восхищаюсь тобой! Ты для меня мечта и воспоминание, будущее и настоящее. Ты – вся моя жизнь!');
Insert into COMPLIMENTS (ID,TEXT) values (193,'Милая, знай что ты изо дня в день украшаешь этот мир! Наверное, это твоя миссия на земле, ведь без твоей яркой улыбки, без твоего лучезарного взгляда и веселого смеха все вокруг теряет краски и становится тусклым! Ты прекрасна, словно невиданный цветок!');
Insert into COMPLIMENTS (ID,TEXT) values (194,'В твоём сердце столько теплоты, что с лихвой хватит на целый мир! А твоя потрясающая красота – это не просто редкость, это уникальный случай внутреннего и внешнего совершенства!');
Insert into COMPLIMENTS (ID,TEXT) values (195,'Ты – изысканный бриллиант, ты – нежный цветок, ты – сияющая звезда! Я мог бы продолжить, но в этом нет смысла, ведь ты – несравненна, моя любимая!');
Insert into COMPLIMENTS (ID,TEXT) values (196,'Солнышко, ты пленила меня своими красотой и обаянием! Я так хочу увидеть тебя вновь, чтобы насладиться каждым мгновением, проведенным с тобой, прелестная куколка!');
Insert into COMPLIMENTS (ID,TEXT) values (197,'Ты не просто красавица, ты – настоящая колдунья. И твои чары самое прекрасное, что могло произойти со мной в жизни.');
Insert into COMPLIMENTS (ID,TEXT) values (198,'Видеть тебя – наслаждение для глаз, слышать твой голос – блаженство для слуха, обнимать тебя – самое большое счастье.');
Insert into COMPLIMENTS (ID,TEXT) values (199,'Любимая, только ты способна вдохновить меня на подвиги! Ты – моя прекрасная принцесса, изящнее и нежнее которой нет на всём было свете!');
Insert into COMPLIMENTS (ID,TEXT) values (200,'Мой нежный ангел, я не перестаю восхищаться неземной красотой! Ты – лучшее творение Бога и самая прекрасная девушка во Вселенной!');
Insert into COMPLIMENTS (ID,TEXT) values (201,'Солнышко моё, как же я тебя обожаю! Ты сама не представляешь, насколько ты удивительна и неповторима! Когда я встретил тебя, все другие девушки перестали для меня существовать!');
Insert into COMPLIMENTS (ID,TEXT) values (202,'Любимая, ты настолько прекрасна, что по сравнению с тобою меркнут даже звёзды! Я бесконечно счастлив, что встретил тебя, ведь ты – сокровище, ценность которого невозможно ничем измерить!');
Insert into COMPLIMENTS (ID,TEXT) values (203,'Моя дорогая, я огромный счастливчик, ведь мне повезло встретить такую роскошную девушку, как ты! Милая, ты такая красивая, нежная, обаятельная и сексуальная, что я начинаю сходить с ума, если мы не видимся хотя бы один день!');
Insert into COMPLIMENTS (ID,TEXT) values (204,'Любимая, ты такая соблазнительная, манящая, чувственная и сексуальная!');
Insert into COMPLIMENTS (ID,TEXT) values (205,'Ты мечта любого мужчины: красивая, умная, ласковая, нежная, очаровательная. И я счастлив, что этот алмаз достался мне.');
Insert into COMPLIMENTS (ID,TEXT) values (206,'Ты – самая яркая звёздочка на небосклоне моей жизни! Твоя любовь – это кристально чистый воздух, которым я дышу и без которого не могу ни секунды!');
Insert into COMPLIMENTS (ID,TEXT) values (207,'Любовь моя, свет твоих глаз подобен сиянию звёзд, прикосновения твоих рук нежнее шёлка, а твой голос слаще любой музыки. Я тебя обожаю!');
Insert into COMPLIMENTS (ID,TEXT) values (208,'Любимая, твоя утончённая красота заставляет моё сердце замирать, а твоё бьющее фонтаном обаяния – бешено колотиться! Ты – уникальная девушка!');
Insert into COMPLIMENTS (ID,TEXT) values (209,'Я люблю твою лучезарную улыбку, твои нежные уста и грациозную фигуру!');
Insert into COMPLIMENTS (ID,TEXT) values (210,'Нежная, милая, страстная, элегантная, очаровательная, восхитительная – что объединяет эти слова? Все они – о тебе, моя любимая!');
Insert into COMPLIMENTS (ID,TEXT) values (211,'Жизнь с тобой подобна сказке. Ведь ты – прекрасная принцесса. Для тебя все мои свершения и все мои победы посвящены тебе.');
Insert into COMPLIMENTS (ID,TEXT) values (212,'Ты – сама нежность, хрупкость и женственность, но один твой пылкий взгляд может положить меня на лопатки.');
Insert into COMPLIMENTS (ID,TEXT) values (213,'Любимая моя, в тебе удивительным образом сочетаются все лучшие человеческие качества: доброта, милосердие, мудрость. И всё это – на фоне сногсшибательной, невероятной красоты!');
Insert into COMPLIMENTS (ID,TEXT) values (214,'Только рядом с тобой, такой прекрасной и восхитительной, я становлюсь лучше, чем я есть.');
Insert into COMPLIMENTS (ID,TEXT) values (215,'Любимая, я не могу представить девушку прекраснее тебя, потому что такой быть не может! Голос, улыбка, фигура, душевные качества – ты идеальна во всём без исключения!');
Insert into COMPLIMENTS (ID,TEXT) values (216,'Невозможно оторвать глаз от тебя, моя дорогая! Ты прекрасна с макияжем и без, с укладкой и гулькой на скорую руку, в лучших нарядах и нагишом, когда ты бодрствуешь и когда ты спишь...');
Insert into COMPLIMENTS (ID,TEXT) values (217,'Любовь моя, мое сокровище, ты самое ценное, что у меня есть! Ты тот идеал, который однажды я нарисовал в своем воображении, и даже не надеялся встретить в этой жизни, но ты со мной, а значит, мне удалось! И еще знай, у тебя нет недостатков, ведь идеалы совершенны!');
Insert into COMPLIMENTS (ID,TEXT) values (218,'Любимая, даже трудно поверить, что я встретил тебя в реальной жизни, ведь ты – идеальное воплощение всех моих мыслей, желаний и снов! Спасибо за то, что ты есть!');
Insert into COMPLIMENTS (ID,TEXT) values (219,'Ясное моё солнышко, мой ласковый котёнок! Как же мне хочется прижать тебя к себе и никогда не отпускать! Ты – самая нежная, добрая и очаровательная девушка во всей Вселенной!');
Insert into COMPLIMENTS (ID,TEXT) values (220,'Ты прекраснее всех в мире цветов, твоя улыбка сияет ярче солнца, а душа чище горных озер! Мне так повезло встретить такую чудесную девушку, как ты!');
Insert into COMPLIMENTS (ID,TEXT) values (221,'Ты не просто девушка, ты – волшебница, потому что встреча с тобой самым чудесным образом изменила мою жизнь. Только благодаря твоим чарам, я понял, что такое счастье!');
Insert into COMPLIMENTS (ID,TEXT) values (222,'Я не знаю, сколько времени потребуется, чтобы перечислить все твои достоинства, моя любимая. Но я уверен в одном – любить тебя я буду бесконечно!');
Insert into COMPLIMENTS (ID,TEXT) values (223,'Любимая, ты не похожа на богиню, ты и есть богиня! Я преклоняюсь перед твоей фантастической красотой и душевной чистотой! Ты – мой мир, мой воздух, моя жизнь!');
Insert into COMPLIMENTS (ID,TEXT) values (224,'Ты просто невероятная девушка! Нежная – и в то же время страстная, гордая – и в то же время милая. Только когда я встретил тебя, моя жизнь обрела смысл!');
Insert into COMPLIMENTS (ID,TEXT) values (225,'Моя дорогая, с каждым днем я все больше и больше убеждаюсь, что мне досталась лучшая женщина в мире, ведь ты не только красива, но еще и невероятно умна, имеешь доброе сердце и множество талантов!');
Insert into COMPLIMENTS (ID,TEXT) values (226,'Любимая, ты подобна драгоценной жемчужине, только ещё прекраснее, ярче, изящнее! Видеть блеск твоих ласковых глаз – наивысшее счастье для меня!');
Insert into COMPLIMENTS (ID,TEXT) values (227,'Если бы ты спросила волшебное зеркальце: «Кто на свете всех милее?» - оно бы ответило: «Конечно, ты! И других вариантов нет!» Ты действительно сказочно хороша!');
Insert into COMPLIMENTS (ID,TEXT) values (228,'Солнышко, если ты рядом, весь мир мне кажется прекраснее, ярче и добрее! Ты наполняешь мою жизнь счастьем, любовью и гармонией! Ты прекрасна, как невиданный цветок, словно ангел, спустившийся с небес, будто принцесса из самой доброй сказки!');
Insert into COMPLIMENTS (ID,TEXT) values (229,'Любимая, я не устаю восхищаться тобой, ведь с каждым днем я все больше и больше убеждаюсь в том, что мне досталась самая красивая, умная, хозяйственная и добрая девушка на земле! Я люблю в тебе все: каждую мелочь, каждый жест и взгляд, даже то, что ты считаешь своими минусами, в моих глазах - твои сильные стороны!');
Insert into COMPLIMENTS (ID,TEXT) values (230,'Ты – яркая, элегантная, уверенная в себе леди! Перед твоим обаянием невозможно устоять, и на тебя нельзя смотреть без восхищения!');
Insert into COMPLIMENTS (ID,TEXT) values (231,'Ты – шикарная женщина! Природа наделила тебя естественной, удивительной красотой, а Господь подарил тебе светлую, чистую душу!');
Insert into COMPLIMENTS (ID,TEXT) values (232,'Любимая, моё восхищение твоей неземной красотой не знает границ! А моя любовь к тебе настолько велика, что с ней не сравнится даже необъятная Вселенная!');
Insert into COMPLIMENTS (ID,TEXT) values (233,'Моя радость, ты самая красивая, искренняя, лучезарная и очаровательная девушка, которую я когда-либо встречал! Когда ты ангельски улыбаешься и смотришь на меня таким манящим, пронизывающим взглядом, я схожу с ума! Все, что я искал, я нашел в тебе, моя любовь!');
Insert into COMPLIMENTS (ID,TEXT) values (234,'Такой девушки, как ты, в мире больше нет! Ты – добрая, ласковая, отзывчивая, утончённая, мудрая. А о твоей красоте можно слагать поэмы!');
Insert into COMPLIMENTS (ID,TEXT) values (235,'Такая девушка, как ты, достойна всех сокровищ Земли и всех звёзд, что сияют на небе! Впрочем, таких, как ты, больше нет. Ты – уникальна, удивительна и безупречна во всём!');
Insert into COMPLIMENTS (ID,TEXT) values (236,'Любовь моя, секрет твоего волшебного очарования невозможно разгадать, но зато я точно знаю – мне безумно повезло встретить тебя! Ты не просто прелестна, ты совершенна!');
Insert into COMPLIMENTS (ID,TEXT) values (237,'Твой нежный образ настолько гармоничен, что кажется будто ты сошла со страниц гениального романа о любви. Ты нереально прекрасна!');
Insert into COMPLIMENTS (ID,TEXT) values (238,'Любовь моя, сказать, что ты прекрасна – значит, ничего не сказать. Ты – блистательна, изящна, превосходна, несравненна! Впервые тебя увидев, я начал верить в чудеса, ведь наша встреча и есть – настоящая чудо!');
Insert into COMPLIMENTS (ID,TEXT) values (239,'Любимая, только ты способна зажечь в моём сердце яркий фейерверк чувств: обожание, нежность, страсть, желание всегда быть рядом и делать тебя счастливой! Ты – бесподобная девушка!');
Insert into COMPLIMENTS (ID,TEXT) values (240,'Ты – эталон истинной женской красоты! И твоё главное предназначение на этой Земле – восхищать, очаровывать, наслаждаться своим совершенством!');
Insert into COMPLIMENTS (ID,TEXT) values (241,'Ты – художница, наполняющая мою жизнь яркими красками! Ты – волшебница, исполнившая мою мечту – быть счастливым! Спасибо, моя родная, за всё!');
Insert into COMPLIMENTS (ID,TEXT) values (242,'Я до сих пор задаюсь вопросом: за что, за какие заслуги, мне послано такое счастье, как ты?! Я по уши влюблен в тебя, и невероятно рад, что рядом со мной такая великолепная девушка! Ты ангел, снизошедший на землю, которого я буду холить и лелеять всю жизнь!');
Insert into COMPLIMENTS (ID,TEXT) values (243,'Моя дорогая, ты всегда была моей мечтой, которая однажды осуществилась! Я так счастлив, что встретил тебя, идеальную девушку: ты не только красавица, а еще и моя родственная душа! Я очень ценю это, и люблю в тебе все: каждую ямочку на щечках, все твои родинки, длинные ресницы, грациозную походку... Все-все до мелочей! Ты прекрасна!');
Insert into COMPLIMENTS (ID,TEXT) values (244,'Любимая, ты достойна того, чтобы весь мир был у твоих ног! Потому что ты – прекраснее и желаннее всех в мире!');
Insert into COMPLIMENTS (ID,TEXT) values (245,'Ты, никак иначе, прекрасная богиня, что снизошла с небес на землю, ведь раньше я никогда не встречал таких обворожительных и сказочно красивых девушек, как ты!');
Insert into COMPLIMENTS (ID,TEXT) values (246,'Какое поразительное сочетание красоты, ума и доброго сердца! Ты, несомненно, редкий экземпляр, ведь таких прелестных леди, которые обладают не только красивой внешность, а и чистой душой, так мало! Ты настоящее чудо и я просто пребываю в восхищении!');
Insert into COMPLIMENTS (ID,TEXT) values (247,'Невозможно описать словами то, насколько ты обворожительна, но я все-таки попробую! Твое личико прекрасно, словно личико фарфоровой куколки, волосы гладки, будто шелк, а фигура грациозна и утонченна, как у длинноногой лани! В тебе нет изъянов, ты настоящее произведение искусства!');
Insert into COMPLIMENTS (ID,TEXT) values (248,'Ты достойна того, чтобы весь этот необъятный мир был у твоих ног, потому что в нём нет девушки прекраснее!');
Insert into COMPLIMENTS (ID,TEXT) values (249,'Когда я гляжу на тебя, мое сердце замирает, ведь ты восхитительна! Твои прекрасные, ангельские черты лица завораживают, элегантные жесты и манеры очаровывают, а изящная фигура приводит в восторг! Знай, что ты самая красивая девушка, которую я когда-либо встречал!');
Insert into COMPLIMENTS (ID,TEXT) values (250,'Милая, знай, что ты прекраснее всех звезд во вселенной, даже самых ярких, красивее всех на свете цветов, даже самых необыкновенных, и ценнее всех в мире бриллиантов, даже самых дорогих!');
Insert into COMPLIMENTS (ID,TEXT) values (251,'Если ты хочешь увидеть самую прекрасную, нежную, великолепную, очаровательную девушку во Вселенной – просто посмотри в зеркало!');
Insert into COMPLIMENTS (ID,TEXT) values (252,'Ты прекрасный цветок, который я буду как заботливый садовник поливать любовью всю жизнь!');
Insert into COMPLIMENTS (ID,TEXT) values (253,'Говорят, что можно бесконечно смотреть на огонь и воду. А я могу бесконечно смотреть в твои добрые, глубокие глаза, моя любимая, и просто наслаждаться тем, что ты рядом!');
Insert into COMPLIMENTS (ID,TEXT) values (254,'Любимая, ты само очарование, и мне так нравится твой озорной взгляд, твоя загадочная улыбка и чарующая непредсказуемость! Ты тайна, которую я буду разгадывать всю жизнь!');
Insert into COMPLIMENTS (ID,TEXT) values (255,'Мое солнышко, ты освещаешь мою жизнь счастьем и согреваешь меня своей любовью! Знай, родная, что ты само совершенство, сама естественность, ты воплощение женственности, нежности и ангельской красоты!');
Insert into COMPLIMENTS (ID,TEXT) values (256,'Милая моя, родная девочка, моя ясная звёздочка! Знай, никто не сравнится с тобою, ведь ты – само совершенство!');
Insert into COMPLIMENTS (ID,TEXT) values (257,'Я хочу, чтобы ты всегда помнила о том, что ты прекрасна, восхитительна и неотразима! Я гляжу на тебя и понимаю, что ты настоящая богиня, которую я каким-то чудом повстречал на земле, ведь ты не только красива внешне, но и чиста душой, невероятно мудра и воистину многогранна!');
